actions.script:
// the playlist as the viewer: one they may not read, or one that is no playlist, is not available
const wall = ec.resource.script('component://tools/template/ReportPlaylists.js').wall(definitionId)
playlistTitle = wall.title; playlistSeconds = wall.seconds
// the range is the mount's (relative, so it needs no zone); the data transition takes the playlist's index
const rangeQuery = '&from=' + encodeURIComponent(wall.range.from) + '&thru=' + encodeURIComponent(wall.range.thru)
wallRange = wall.range
playlistEntries = wall.entries.map(entry => ({index: entry.index, title: entry.title, url: '?definitionId=' + encodeURIComponent(entry.id) + rangeQuery}))
dataSource = sri.buildUrl('data').path + '?definitionId=' + encodeURIComponent(definitionId || '') + rangeQuery
// the html page: the theme's style sheets, the qvt client's files and this screen as an island (WebrootPublic.qvt.js)
const qvtLib = ec.resource.script('component://webroot/screen/includes/QvtConfig.js')
const localeTag = String(ec.user.locale || 'en_US').replace('_', '-')
const quasarLang = qvtLib.quasarLangOf(localeTag)
const sheets = Array.from(sri.getThemeValues('STRT_STYLESHEET'))
const scripts = ['/libs/vue/vue.global.prod.js', '/libs/quasar/quasar.umd.prod.js', '/libs/quasar/lang/' + quasarLang + '.umd.prod.js']
if (sheets.some(sheet => String(sheet).includes('/libs/material-symbols/'))) scripts.push('/libs/quasar/icon-set/material-symbols-outlined.umd.prod.js')
scripts.push('/js/MoquiLib.js', '/js/MoquiL10n.js', '/js/WebrootVue.qvt.render.js', '/js/WebrootVue.qvt.js', '/js/WebrootReport.js', '/js/WebrootPublic.qvt.js')
const version = '?v=' + ec.web.getResourceDistinctValue()
const href = location => WebUtilities.encodeHtml(sri.buildUrl(location).url + version)
wallHead = sheets.map(sheet => '<link rel="stylesheet" href="' + href(sheet) + '">').join('')
wallScripts = scripts.map(script => '<script src="' + href(script) + '"></script>').join('')
wallLang = WebUtilities.encodeHtml(localeTag)
wallTitle = WebUtilities.encodeHtml(playlistTitle || ec.l10n.localize('Wall display'))
const island = {
    shell: 'island', sessionToken: ec.web.sessionToken, appRootPath: '', locale: localeTag, timeZone: ec.user.timeZone,
    quasarLang: quasarLang.replace(/-([a-zA-Z])/g, (m, ch) => ch.toUpperCase()),
    qvt: {build: 'compiler', handles: ['merged-fragment', 'static-template']},
    route: {name: 'wall-display', basePath: sri.buildUrl('.').path, title: playlistTitle, renderModes: ['qvt']},
    context: {}, labels: {loading: ec.l10n.localize('Loading'), notFound: ec.l10n.localize('This playlist is not available to this display.')}
}
wallIsland = JSON.stringify(island).split('<').join('\\u003c')
